import{_ as o,o as t,c as i,a3 as a}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Hermeticity","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Hermeticity | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/hermeticity"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/hermeticity"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/hermeticity"}]]},"headers":[],"relativePath":"xclang/design/hermeticity.md","filePath":"en/xclang/design/hermeticity.md","lastUpdated":1794509097000}'),c={name:"xclang/design/hermeticity.md"};function d(s,e,n,r,l,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="hermeticity" tabindex="-1">Hermeticity <a class="header-anchor" href="#hermeticity" aria-label="Permalink to &quot;Hermeticity&quot;">​</a></h1><p>xclang holds every target to one rule:</p><blockquote><p>A program depends at run time only on the system libraries every installation of its OS has and no one may redistribute. Everything else is linked into it. At build time, the only inputs from outside the toolchain are vendor SDKs.</p></blockquote><p>Every bundled target and every target on the <a href="./roadmap#targets">roadmap</a> follows this rule. A compiled binary is a single file that runs on any machine of its target OS floor without installing a C++ runtime package or shipping runtime DLLs alongside it.</p><p>At build time, the only inputs from outside the toolchain are vendor SDKs that no one may redistribute (<a href="./../guide/cross-compiling#vendor-sdks">vendor SDKs</a>):</p><ul><li><strong>macOS targets</strong>: on macOS hosts, <code>clang</code> builds against Xcode&#39;s or the Command Line Tools&#39; SDK (<code>xcrun</code>), which xclang does not pin. On Linux and Windows hosts, <code>xclang sdk fetch macos</code> downloads Apple&#39;s SDK pinned by version, <code>sha256</code> and content digest (<a href="./macos#apple-s-sdk-without-xcode">macOS</a>).</li><li><strong>Windows MSVC targets</strong>: <code>xclang sdk fetch windows</code> downloads Microsoft&#39;s CRT, STL and Windows SDK pinned by version and <code>sha256</code> (<a href="./windows#the-sdk-without-visual-studio">Windows</a>). On a Windows host with no SDK fetched, <code>clang</code> falls back to an installed Visual Studio, which xclang does not pin.</li></ul><h2 id="what-a-program-loads" tabindex="-1">What a Program Loads <a class="header-anchor" href="#what-a-program-loads" aria-label="Permalink to &quot;What a Program Loads&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>loaded at run time from the system</th><th>linked statically</th></tr></thead><tbody><tr><td>Linux (glibc)</td><td>glibc 2.17 or later: <code>libc</code>, <code>libm</code>, <code>libpthread</code>, <code>libdl</code>, <code>librt</code>, the dynamic loader</td><td><code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code>, <code>compiler-rt</code> builtins</td></tr><tr><td>Linux (musl)</td><td>nothing: Linux kernel system calls only</td><td><code>musl</code>, <code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code>, <code>compiler-rt</code> builtins</td></tr><tr><td>macOS</td><td><code>libSystem</code> (the C library and unwinder) and the system frameworks the program links</td><td><code>libc++</code>, <code>libc++abi</code>, <code>compiler-rt</code> builtins</td></tr><tr><td>Windows (MinGW)</td><td>Windows OS DLLs (<code>kernel32.dll</code>, ...) and UCRT (<code>api-ms-win-crt-*</code>), part of Windows 10 and later</td><td><code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code>, <code>compiler-rt</code> builtins, <code>winpthreads</code>, the <code>mingw-w64</code> runtime</td></tr><tr><td>Windows (MSVC)</td><td>Windows OS DLLs and UCRT (<code>ucrtbase.dll</code>), as for MinGW</td><td><code>libc++</code> (or Microsoft&#39;s STL), Microsoft&#39;s VC runtime (<a href="./windows#the-hybrid-crt">the hybrid CRT</a>), <code>compiler-rt</code> builtins</td></tr></tbody></table><p>The libraries in the middle column cannot be linked into or redistributed with a program: glibc&#39;s dynamic loader and <code>libc</code> form one ABI with the host system, <code>libSystem</code> is the only supported interface to the macOS kernel, and UCRT and the system DLLs are OS components of Windows 10 and later. Everything in the right column can be linked into the binary, and xclang links it statically by default.</p><p>The toolchain binaries follow the same rule. <code>clang</code>, <code>lld</code>, the LLVM binary tools and <code>xclang</code> are linked statically against xclang&#39;s own <code>libc++</code> on every host, macOS included, and never load <code>/usr/lib/libc++.1.dylib</code>.</p><p>The one test-only exception is dynamic sanitizer runtimes (<a href="./../features/sanitizers">sanitizers</a>). On macOS, the sanitizer runtimes are <code>.dylib</code> files loaded from the toolchain or the binary&#39;s directory (<a href="./macos#the-sanitizers-dylibs">the sanitizers&#39; dylibs</a>). On <code>x86_64</code> Windows (MinGW and MSVC), the AddressSanitizer runtime is a DLL loaded from the binary&#39;s directory or <code>PATH</code> (<a href="./windows#asan-s-dll">ASan&#39;s DLL</a>). Sanitizer builds are for testing, not shipping.</p><h2 id="why-not-shared-runtimes" tabindex="-1">Why Not Shared Runtimes <a class="header-anchor" href="#why-not-shared-runtimes" aria-label="Permalink to &quot;Why Not Shared Runtimes&quot;">​</a></h2><p>Most toolchains link a shared <code>libc++</code> or <code>libstdc++</code> by default, which shifts three costs onto deployment:</p><ul><li><strong>The program needs the runtime installed on the target machine.</strong> On Linux, <code>libc++.so.1</code> is not part of a default OS installation, so a binary linked against it needs a system package, a bundled copy via <code>DT_RUNPATH</code>, or a container. On Windows, <code>libc++.dll</code>, <code>libunwind.dll</code> and <code>libwinpthread-1.dll</code> (or <code>vcruntime140.dll</code> and <code>msvcp140.dll</code>) must be shipped beside every executable.</li><li><strong>The runtime version is the target machine&#39;s, not the build&#39;s.</strong> A shared library loaded from the OS is whatever version that machine happens to have, not the version the program was compiled and tested with. On macOS, linking <code>/usr/lib/libc++.1.dylib</code> ties C++ library features to the target macOS version rather than the toolchain release (<a href="./macos#why-xclang-s-libc-and-not-the-system-s">macOS</a>).</li><li><strong>The build environment leaks into the binary.</strong> conda-forge&#39;s compilers link against the <code>libcxx</code> and <code>libstdcxx</code> conda packages and record them in a package&#39;s runtime dependencies through <code>run_exports</code>. Inside a conda environment that provides those packages, that works; outside conda, the resulting binaries depend on shared libraries that user machines do not have. Because xclang links its runtimes statically into every binary and has no <code>run_exports</code>, it is not a compiler for building conda-forge packages (<a href="./roadmap#conda-forge">roadmap</a>).</li></ul><p>The price of static runtimes is binary size, since each executable carries the parts of <code>libc++</code> it uses, and one private copy of <code>libc++</code> in each shared object.</p><h2 id="one-libc-per-shared-object" tabindex="-1">One libc++ per Shared Object <a class="header-anchor" href="#one-libc-per-shared-object" aria-label="Permalink to &quot;One libc++ per Shared Object&quot;">​</a></h2><p><code>libc++</code>, <code>libc++abi</code> and <code>libunwind</code> are built as position-independent static archives (<code>CMAKE_POSITION_INDEPENDENT_CODE=ON</code>) with hidden symbol visibility (<code>LIBCXX_HERMETIC_STATIC_LIBRARY=ON</code>, <code>LIBCXXABI_HERMETIC_STATIC_LIBRARY=ON</code>, <code>LIBUNWIND_HIDE_SYMBOLS=ON</code>). Every executable and every shared library (<code>-shared</code>) linked by xclang carries its own private copy of <code>libc++</code>, with no symbols exported to other shared objects (<a href="./roadmap#shared-runtime">shared runtime on the roadmap</a>).</p><p>When an application loads more than one shared object linked this way, it faces the same constraints the <a href="https://developer.android.com/ndk/guides/cpp-support" target="_blank" rel="noreferrer">Android NDK documents</a> for its static <code>libc++</code>:</p><ul><li><strong>C++ objects and allocations must not cross shared-object boundaries.</strong> A <code>std::string</code> or <code>std::vector</code> constructed in one shared object and destroyed or resized in another mixes the state of two runtime copies. Memory allocated in one shared object must be freed in the same shared object.</li><li><strong>Exceptions and RTTI across shared objects.</strong> Each copy has its own <code>std::type_info</code> instances for <code>std::exception</code> and the other standard types. On Linux and macOS, <code>libc++</code> compares <code>type_info</code> by address, so a standard exception thrown in one shared object is caught in another only by <code>catch (...)</code>, not by <code>catch (const std::exception&amp;)</code>. Comparing <code>type_info</code> by name everywhere would cost a string comparison on every mismatch and merge same-named types in anonymous namespaces, so xclang keeps upstream <code>libc++</code>&#39;s default. On Windows, <code>type_info</code> is compared by name and catches across DLLs when both sides share one ABI.</li><li><strong>Process-wide <code>libc++</code> globals are per shared object</strong>: the buffer of <code>std::cout</code>, <code>std::locale::global</code>, <code>std::set_new_handler</code> and <code>std::set_terminate</code>.</li></ul><p>A program that links its C++ libraries statically into one executable has none of these problems, which is why the <a href="./bazel-module#static-by-default">Bazel module links libraries statically by default</a>. Across shared-object or plugin boundaries, expose a C interface.</p><h2 id="why-glibc-2-17" tabindex="-1">Why glibc 2.17 <a class="header-anchor" href="#why-glibc-2-17" aria-label="Permalink to &quot;Why glibc 2.17&quot;">​</a></h2><p>glibc versions its symbols, and the linker binds each symbol to the newest version present in the build sysroot&#39;s <code>libc.so.6</code>. A Linux binary therefore runs on the glibc version it was linked against and any later version, never an earlier one.</p><p>xclang&#39;s Linux sysroots carry the headers, startup objects and stub libraries of glibc 2.17 (taken from CentOS 7 via conda-forge&#39;s <code>sysroot_linux-64</code> and <code>sysroot_linux-aarch64</code> 2.17 packages), the same floor used by conda-forge and <a href="https://github.com/rust-lang/rust/blob/main/src/ci/docker/host-x86_64/dist-x86_64-linux/Dockerfile" target="_blank" rel="noreferrer">Rust&#39;s official Linux targets</a>. What glibc 2.17 lacks (<code>-static-pie</code>, <code>-pg</code> with PIE, and <code>quadmath.h</code>) is covered in <a href="./../guide/cross-compiling#glibc-2-17-floor-static-pie-and-pg">cross-compiling</a>, and a newer glibc target is <a href="./roadmap#glibc-newer">considered</a>. Because glibc 2.17 predates <code>__cxa_thread_atexit_impl</code> (added in glibc 2.18), <code>libc++abi</code> is built with <code>LIBCXXABI_HAS_CXA_THREAD_ATEXIT_IMPL=OFF</code> so it references the symbol weakly and falls back to its own <code>thread_local</code> destructor list on glibc 2.17.</p><p>Two adjustments in <code>toolchain/sysroot.ts</code> make the glibc 2.17 sysroots work across hosts and link modes:</p><ul><li><strong><code>-static</code> links.</strong> glibc 2.17&#39;s <code>libpthread.a</code> is a single object file that redefines <code>__libc_sigaction</code> and cancellation points from <code>libc.a</code>. Because <code>libunwind</code>&#39;s dependent-library note pulls in <code>libpthread.a</code> after <code>libc.a</code>, <code>-static</code> links failed with duplicate symbol errors. The sysroot renames <code>libc.a</code> to <code>libglibc.a</code> and replaces <code>libc.a</code> with a linker script, <code>GROUP ( /usr/lib64/libpthread.a /usr/lib64/libglibc.a )</code>, so both archives are searched together in an order that links cleanly.</li><li><strong>No symbolic links or case collisions.</strong> Creating symbolic links on Windows requires elevated privileges or Developer Mode, and conda packages for Windows cannot carry them. In the Linux sysroots, directory links (<code>lib -&gt; lib64</code>) are resolved in linker scripts and removed, soname links (<code>libc.so.6 -&gt; libc-2.17.so</code>) are replaced by the files themselves, and <code>.so</code> development links (<code>libm.so</code>) become <code>INPUT ( ... )</code> linker scripts like glibc&#39;s own <code>libc.so</code>. Netfilter headers whose filenames differ only in case (<code>xt_DSCP.h</code> beside <code>xt_dscp.h</code>) keep only the lowercase file so every archive unpacks on case-insensitive file systems.</li></ul><h2 id="gcc-library-names" tabindex="-1">GCC Library Names <a class="header-anchor" href="#gcc-library-names" aria-label="Permalink to &quot;GCC Library Names&quot;">​</a></h2><p>Build scripts written for GCC name GCC&#39;s runtime libraries on the link line: <code>-latomic</code> for wide atomics, <code>-lgcc_s</code> and <code>-lgcc_eh</code> for the unwinder, <code>-lgcc</code> for compiler builtins, and <code>-lssp</code> for the stack protector on MinGW. In xclang, those functions live in <code>compiler-rt</code>, <code>libunwind</code> and <code>mingw-w64</code>. The Linux, musl and MinGW sysroots therefore provide empty archive stubs (<code>!&lt;arch&gt;\\n</code>) under those names so GCC link lines succeed without changes:</p><ul><li><strong><code>-latomic</code></strong>: the <code>__atomic_*</code> functions for atomics too wide to be lock-free (structs, or <code>__int128</code> without <code>cx16</code>) are built into the <code>compiler-rt</code> builtins (<code>COMPILER_RT_EXCLUDE_ATOMIC_BUILTIN=OFF</code>).</li><li><strong><code>-lgcc</code>, <code>-lgcc_s</code>, <code>-lgcc_eh</code></strong>: compiler helpers and unwinding come from <code>compiler-rt</code> and <code>libunwind</code>. Because <code>libgcc_s.a</code> and <code>libgcc_eh.a</code> are empty archives, linking with <code>-nodefaultlibs</code> (as <code>rustc</code> does on <code>*-unknown-linux-gnu</code>) gets no unwinder unless <code>-l:libunwind.a</code> is passed; <code>xclang cargo</code> handles this automatically (<a href="./../integrations/cargo#what-xclang-cargo-sets">Rust and Cargo</a>, and making <code>libgcc_s.a</code> a linker script is <a href="./roadmap#libgcc-s-script">considered</a>).</li><li><strong><code>-lssp</code>, <code>-lssp_nonshared</code></strong>: <code>clang</code>&#39;s MinGW driver adds these for <code>-fstack-protector</code>; the functions are provided by <code>libmingwex.a</code> in <code>mingw-w64</code>.</li><li><strong><code>-lstdc++</code></strong>: needs no stub archive because the <code>clang</code> driver replaces <code>-lstdc++</code> with <code>-lc++</code> unless <code>-nostdlib</code>, <code>-nodefaultlibs</code> or <code>-nostdlib++</code> is passed.</li><li><strong><code>windres</code></strong>: linked to <code>llvm-windres</code> in <code>bin/</code>, the tool name CMake&#39;s MinGW platform module looks for when compiling <code>.rc</code> files.</li></ul><h2 id="static-programs-with-musl" tabindex="-1">Static Programs with musl <a class="header-anchor" href="#static-programs-with-musl" aria-label="Permalink to &quot;Static Programs with musl&quot;">​</a></h2><p>Unlike glibc, musl is built to be linked statically. The <code>x86_64-unknown-linux-musl</code> and <code>aarch64-unknown-linux-musl</code> targets link musl 1.2.6 (compiled with <code>--disable-shared</code> and asynchronous unwind tables), <code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code> and <code>compiler-rt</code> into a static executable with no program interpreter (<code>PT_INTERP</code>) and no dynamic section, removing even the C library from the runtime dependencies.</p><p>The trade-offs of static musl binaries:</p><ul><li><strong>Binary size</strong>: musl adds 51 KB unstripped (27 KB stripped) to a C++ <code>iostream</code> hello-world program on Linux x64 (1.17 MB vs 1.12 MB unstripped, 826 KB vs 799 KB stripped).</li><li><strong>No shared libraries or dynamic sanitizers</strong>: the bundled sysroot has no <code>libc.so</code>, so <code>dlopen</code> and <code>-shared</code> libraries are not supported and UBSan is the only available sanitizer (<a href="./../features/sanitizers#musl-targets">sanitizers</a>).</li><li><strong>Runtime behavior differences from glibc</strong>: allocator lock contention under threads, <code>C</code>-only locale formatting, and direct DNS queries without NSS are covered in <a href="./../guide/cross-compiling#musl-targets">cross-compiling</a>.</li></ul><h2 id="the-platform-s-c-library" tabindex="-1">The Platform&#39;s C++ Library <a class="header-anchor" href="#the-platform-s-c-library" aria-label="Permalink to &quot;The Platform&#39;s C++ Library&quot;">​</a></h2><p>A program that passes C++ standard library types across an interface to a library built with the platform&#39;s C++ library (a Linux distribution&#39;s <code>libstdc++</code> packages, a macOS library using <code>/usr/lib/libc++.1.dylib</code>, or a Windows library compiled with MSVC&#39;s STL) must use that same C++ library and ABI. Passing <code>-stdlib=platform</code> deliberately leaves the hermeticity rule by switching to <code>bin/&lt;triple&gt;-system.cfg</code> (<a href="./toolchain#the-platform-s-c-library">toolchain structure</a>); how to use it and what the resulting binary loads at run time on each target are covered in <a href="./../guide/cross-compiling#the-platform-s-c-library">cross-compiling</a>.</p>',34)])])}const p=o(c,[["render",d]]);export{m as __pageData,p as default};
